def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    emit(out, "Start from the input; grey blocks keep their frames, holes will be filled.")

    def norm(cells):
        y0 = min(y for y, x in cells); x0 = min(x for y, x in cells)
        return tuple(sorted((y - y0, x - x0) for y, x in cells))

    def variants(cells):
        arr = np.zeros((max(y for y, x in cells) + 1, max(x for y, x in cells) + 1), dtype=int)
        for y, x in cells:
            arr[y, x] = 1
        res = []
        for k in range(4):
            r = np.rot90(arr, k)
            for f in (r, r[:, ::-1]):
                res.append(norm([(int(y), int(x)) for y, x in zip(*np.nonzero(f))]))
        return res

    allobjs = objects(g, bg=bg)
    greys = [o for o in allobjs if o["colour"] == 5]
    others = [o for o in allobjs if o["colour"] != 5]
    colour_count = {}
    for o in others:
        colour_count[o["colour"]] = colour_count.get(o["colour"], 0) + 1
    # pieces are the unique objects of their colour; scattered colours are noise
    order = [i for i, o in enumerate(others) if colour_count[o["colour"]] == 1] + \
            [i for i, o in enumerate(others) if colour_count[o["colour"]] != 1]
    used = set()

    for blk in greys:
        y0, x0, y1, x1 = blk["box"]
        sub = g[y0:y1 + 1, x0:x1 + 1]
        h, w = sub.shape
        for comp in components(sub != 5):
            if any(y == 0 or x == 0 or y == h - 1 or x == w - 1 for y, x in comp):
                continue  # touches crop border -> not an enclosed hole
            hole = [(y + y0, x + x0) for y, x in comp]
            hs = norm(hole)
            match = None
            for i in order:
                o = others[i]
                if i in used or o["size"] != len(hole):
                    continue
                if norm(o["cells"]) == hs:
                    match = i; break
            if match is None:
                for i in order:
                    o = others[i]
                    if i in used or o["size"] != len(hole):
                        continue
                    if hs in variants(norm(o["cells"])):
                        match = i; break
            if match is None:
                continue
            used.add(match)
            o = others[match]
            for y, x in o["cells"]:
                out[y, x] = bg
            for y, x in hole:
                out[y, x] = o["colour"]
            emit(out, f"Move the colour-{o['colour']} piece into the matching hole of the grey block at rows {y0}-{y1}, cols {x0}-{x1}.")

    emit(out, "All holes filled with their matching pieces; noise cells unchanged.")
    return out
